using namespace std;

void drawLeft(WINDOW* ,vector<string>&  , int );
void drawChat(WINDOW* ,vector<string>&);

int main(){

    //initialize the screen
    initscr();


    vector <string> chat;

    int highlight = 0;


    drawLeft(leftInner, sideMenu, highlight);



    vector<string> text;

    string type="";


    //allow keyboard input in the bottom window
    keypad(bottomInner,true);

    while (true){

        //we then read the keyboard inputs to do operation with
        int typingInput = wgetch(bottomInner);

        switch(typingInput){
            case KEY_UP:{
                highlight=(highlight == 0)? sideMenu.size() -1: highlight-1;
                    drawLeft(leftInner,sideMenu,highlight);
                break;
            }
            case KEY_DOWN:{
                highlight=(highlight == sideMenu.size()-1)? 0: highlight+1;
                    drawLeft(leftInner,sideMenu,highlight);
                break;
            }
            // case KEY_LEFT:{
            //     highlight=(highlight == 0)? sideMenu.size() -1: highlight-1;
            //     break;
            // }
            // case KEY_RIGHT:{
            //     highlight=(highlight == sideMenu.size()-1)? 0: highlight+1;
            //     break;
            // }
            case KEY_ENTER:
            case '\n':{

                if(!type.empty()){

                    text.push_back("You: "+type);
                    //chat.push_back("You: "+type);
                    drawChat(mainInner, text);

                }

                type.clear();

                wclrtoeol(bottomInner);

                mvwprintw(bottomInner,1,1,"Type > ");

                wrefresh(bottomInner);

                break;
            }
            case KEY_BACKSPACE:
            case 127:
            case '\b': {
                if(!type.empty()){
                    type.pop_back();
                }

                wclrtoeol(bottomInner);
                wmove(bottomInner,1,2);

                mvwprintw(bottomInner,1,1,"Type > %s", type.c_str());
                wrefresh(bottomInner);

                break;
            }

        }
        if(typingInput >=32 && typingInput <= 126){

            //cast everything to char to stop display arrow up and down input
            type+=static_cast<char>(typingInput);

            wrefresh(bottomInner);

            wclrtoeol(bottomInner);

            wmove(bottomInner,1,1);

            mvwprintw(bottomInner,1,1,"Type > %s",type.c_str());

            wrefresh(bottomInner);


        }
    }

    endwin();

    return 0;

}

void drawLeft(WINDOW* leftInner, vector<string>& topicList , int highlight){


    int length = topicList.size();

    for(int i=0; i<length ; ++i){

        if(i == highlight){
            //start_color();
            attron(A_REVERSE);
                mvwprintw(leftInner, (i+3) ,1,"> %s",topicList[i].c_str());
            attroff(A_REVERSE);

        }else{
            mvwprintw(leftInner, (i+3) ,1,topicList[i].c_str());
        }

    }

    wrefresh(leftInner);

}

void drawChat(WINDOW* mainInner,vector<string>& text){

    werase(mainInner);


    int numMessages = text.size();

    int chatHeight,chatWidth;

    getmaxyx(mainInner,chatHeight,chatWidth);

    //the function max use a floor of zero, and ruturns where we shoudl start inside the
    //vector pending on screen size
    int displayStart= max(0, static_cast<int>(text.size()) - chatHeight);

    int rowTotal=0;
    for(int i=displayStart; i< numMessages; i++){
        mvwprintw(mainInner,rowTotal++,1,text[i].c_str());
    }

    wrefresh(mainInner);

}

